from dataclasses import dataclass, field
from typing import Optional
from mashumaro import DataClassDictMixin
from mashumaro.helper import field_options
@dataclass
class C(DataClassDictMixin):
 x:int
@dataclass
class P(DataClassDictMixin):
 a: C = field(metadata=field_options(flatten=True, flatten_prefix=True))
 b: C = field(metadata=field_options(flatten=True, flatten_prefix=True))
p=P(C(1),C(2)); print(p.to_dict(), P.from_dict(p.to_dict()))
@dataclass
class Q(DataClassDictMixin):
 c: Optional[C] = field(default_factory=lambda: C(5), metadata=field_options(flatten=True))
print(Q.from_dict({}))
